export function totalPeople(adults, children) {
  return adults + children + 1;
}

import test from "node:test";
import assert from "node:assert/strict";
import { totalPeople } from "./people.mjs";

test("加總成人與兒童", () => assert.equal(totalPeople(2, 1), 3));
test("拒絕負數", () => assert.throws(() => totalPeople(-1, 1)));
test("拒絕小數", () => assert.throws(() => totalPeople(1.5, 1)));

export function totalPeople(adults, children) {
  if (![adults, children].every((value) => Number.isInteger(value) && value >= 0)) {
    throw new TypeError("人數必須是非負整數");
  }
  return adults + children;
}
